import{_ as a,o as t,c as r,a0 as o}from"./chunks/framework.DCluYYrN.js";const m=JSON.parse('{"title":"What is KernelSU?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is-kernelsu.md","filePath":"guide/what-is-kernelsu.md"}'),s={name:"guide/what-is-kernelsu.md"};function i(n,e,l,h,d,u){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="what-is-kernelsu" tabindex="-1">What is KernelSU? <a class="header-anchor" href="#what-is-kernelsu" aria-label="Permalink to &quot;What is KernelSU?&quot;">​</a></h1><p>KernelSU is a root solution for Android GKI devices. It works in kernel mode and grants root permission to userspace apps directly in kernel space.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><p>The main feature of KernelSU is that it&#39;s <strong>kernel-based</strong>. KernelSU works in kernel mode, enabling it to provide a kernel interface that we never had before. For example, it&#39;s possible to add hardware breakpoints to any process in kernel mode, access the physical memory of any process invisibly, intercept any system call (syscall) within the kernel space, among other functionalities.</p><p>Additionally, KernelSU provides a <a href="./metamodule.html">metamodule system</a>, which is a pluggable architecture for module management. Unlike traditional root solutions that bake mounting logic into their core, KernelSU delegates this to metamodules. This allows you to install metamodules like <a href="https://github.com/tiann/KernelSU/tree/main/userspace/meta-overlayfs" target="_blank" rel="noreferrer">meta-overlayfs</a> to provide systemless modifications to the <code>/system</code> partition and other partitions.</p><h2 id="how-to-use-kernelsu" tabindex="-1">How to use KernelSU? <a class="header-anchor" href="#how-to-use-kernelsu" aria-label="Permalink to &quot;How to use KernelSU?&quot;">​</a></h2><p>See <a href="./installation.html">Installation</a>.</p><h2 id="how-to-build-kernelsu" tabindex="-1">How to build KernelSU? <a class="header-anchor" href="#how-to-build-kernelsu" aria-label="Permalink to &quot;How to build KernelSU?&quot;">​</a></h2><p>See <a href="./how-to-build.html">How to build</a>.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><ul><li>Telegram: <a href="https://t.me/KernelSU" target="_blank" rel="noreferrer">@KernelSU</a></li></ul>',11)])])}const p=a(s,[["render",i]]);export{m as __pageData,p as default};
